// ===== sdkdesc.ts
type DescLayout = { module, client, ctor, names?: Record<string,string>, vars?: Record<string,string> /* shared names (results,item,result,created) as the language spells them */ }
type DescSymbols = { accessor, var, plural /* ident(apidef pluralize(e.name)), set by shared code */, module?, alias?, fields? }   // `vars` and `type` removed
type Naming = (model, target, tm: (templateName: string) => string) => { layout, symbols: (e) => Omit<DescSymbols,'plural'>, ident?: (name: string) => string }
type SdkDescription = { ...as v2, template: Record<string,string> /* ProjectName-family substitutions = ctx$.stdrep */ }
sdkDescription(model, target, naming?, stdrep?); templateName(map, name)

// ===== example.ts
type Ref = { role: 'many'|'item'|'one'|'created', entity: Ent, name: string, list?: string }   // name decided by shared code
type Entry = { key, value: Expr, type?: Scalar }                      // type: comment a write member with its type
type Stmt = ... | { k:'call', entity, op, arg, bind, wide, note?: string } | ...   // note: closing comment of a wide arg
type ResultStyle = 'throw'|'raise'|'die'|'pair'|'errslot'|'union'|'wrapped'
type RuntimeFacts = { ...v2, record: string /* may hold {var} */, pairForm?, unwrap?, unusedError?: boolean, listOf?: string /* '{Class}[]' */ }
type MemberKind = 'options'|'utility'|'utilityBase'|'direct'|'prepare'|'tester'|'data'|'match'|'dataGet'|'dataSet'|'matchGet'|'matchSet'|'dataArg'|'matchArg'|'make'|'name'|'client'|'entopts'|'stream'|'streamIterator'|'streamGenerator'|'streamList'|'streamLazy'
type Member = { kind, sig, returns?: string }
type CtorKind = 'defaults'|'explicit'
type RefFacts = { entityBy: 'class'|'Name'|'module', noun: string, entityNoun?: string, heading?: string, none, lits?: {true,false}, setArg?: string,
  keys, maps, container, valueType, ctor: string[], ctorAlts?: {call, kind: CtorKind}[], test: {sig, call, args, alts?: {call, kind}[]}[],
  accessor, op, opMatched?: Partial<Record<OpName,string>>, client: Member[], entity: Member[], direct: {returns, signal?},
  prepare: {returns, fails: 'style'|'value'|'note'}, body, cancel }
type Scope = { declared, local, stmts, section, standalone: boolean }
type Syntax = { fence, facts,
  client(s, desc, sc), call(s, desc, sc, cx),
  each(s, inner, sc, desc, cx), print(s, sc, desc), attempt(s, inner, sc, desc), comment(text), expr(e, sc, desc),
  imports?: (desc, used: Uses) => string[],            // the page's imports; printed once, ahead of the tutorial's and root's client block, never in a standalone block
  notes?: Partial<Record<NoteSlot, string>>,
  before?, program?, ref?: RefSyntax }
type RefSyntax = { facts: RefFacts, type(t), key(container, path) /* [] = the container */, instance(ent, desc), read(value, key) /* result["ok"] */ }
type NoteSlot = `member:${MemberKind}` | 'ctor'|'test'|'instance'|'entity'|'operations'|'features'|'tutorial'|'tutorial:list'|'tutorial:load'|'tutorial:write'|'top'
Builders: refOpBlock (no attempt; bound result/results; list prints items; create typed; update/patch note; a print where facts.unusedError), actionBlock (one call with $action, shown inline in the table's Call column), note(p, slot), newScope(standalone)

Rule for imports (j): a block never decides its own imports. The provider declares the page's import lines once (imports). The shared page prints them ahead of the tutorial's client block and the root quick start's client block, and nowhere else. A standalone block (any REFERENCE example) never prints them, because the page's lanes compile such blocks with the page's imports.
